INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p941657-mkt301', 'stk-phenomenon', 'MKT 301', 'info', '{"desc": "لو فيه الدكتور محمد الغامدي كان بقولك خذها معه وأنت مغمض!\nلكن راح للأسف ومدري يرجع ولاّ هذا هو تقاعده !\n\nالماده خفيفه صراحه وخصوصا مع الغامدي =/\nتعطيك مقدمه بسيطه عن أساسيات التسويق وأساليبه ومقدمه عن مختلف أنماطه\n\nالمشكله الحين مع الشبل يقولون 50% بروجكتات وأساينمنتس!\nيعني غثا … وما أنصحك تآخذ إلكتف وهي غثا!\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-301/115357/3", "user": "Phenomenon", "ts": 1322889329000, "tid": 115357, "pn": 3}}', 1322889329000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p133100-mkt301', 'stk-mgt_man', 'MKT 301', 'info', '{"desc": "السلام عليكم\n\nاذا كان محمد سعيد الغامدي…انا اخذت هذا الكورس عنده… الصراحة ما راح تفهم شي من الشرح حتى السلايدات ما هو اللي عاملها … بس احسن ما فيه ان الاسئلة 95% من السي دي أو الtb بمعنى آخر. يكفيك انك تذاكر كل شابتر بيومها و حتكون المادة سهلة عليك بس انسى تاخذ منه فايده.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-301/53388/2", "user": "MGT_MAN", "ts": 1164182146000, "tid": 53388, "pn": 2}}', 1164182146000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p828670-mkt301', 'stk-t.h.t', 'MKT 301', 'info', '{"desc": "السلام عليكم\n\nشباب اختباري ماركتينق 301 بكره وهو اخر ميجر عندي << يعني مررره مالي نفس للمذاكره\n\nبديت اذاكر … بس الكتاب مررررررره ما يساعد … دش كلااااااااااااااااااااااام من غير فايده\n\nومن كثر ماني قاعد اقرا ما طلعت بفاااايده\n\nانا اللي عندي الكتاب الجديد 15 … الدكتور قال المحتوى ما يختلف عن القديم\n\nاسعفوني يا شباب بالحل … ماهو السبيل لمذاكره هذا الكتاب الممل 😞", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt-301/105964/1", "user": "T.H.T", "ts": 1301657832000, "tid": 105964, "pn": 1}}', 1301657832000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p77021-mkt301', 'stk-decision_maker', 'MKT 301', 'info', '{"desc": "هلا أخوي\n\nيمكن تأخر جوابي كثير\n\nلكن هالجواب رح يفيدك و يفيد الي بياخذ المادة بعدين\n\nالدكتور كالسج ما يطيق طلاب الأم آي اس خير شر و يحسهم عالة على المجتمع\n\nو الله من جد أتكلم\n\nأنا ماخذ معاه هالسمستر و فعلا هو عنصري مع طلاب الماركتنج\n\nبالنسبة لاختباراته تقدر تاخذ فيها فل مارك\n\nلأن أنا اخذت معاه 3 مياجر و فاينل و كل الأسئلة كانت من السي دي الي يجي\n\nمع الكتاب طبعا هو يضيف سؤال أو سؤالين عبارة عن مقال تكتبه بناء ً على\n\nالسؤال …\n\nبس انه كويس و و اللي ياخذ معاه يتأسس كويس\n\nو الله يوفق الجميع\n\nصانع قرار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt301/42813/6", "user": "Decision_Maker", "ts": 1118324531000, "tid": 42813, "pn": 6}}', 1118324531000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p616015-mkt301', 'stk-user5961', 'MKT 301', 'srcP', '{"html": "السلام عليكم,<br><br>بالنسبه لميجر 4 راح يكون فيه اتوقع 7 أسئله تحل منها 5 واحد من السبعه لازم تحله اجباري وهو توصيل اربعين مصطلح بخمسين تعريف تقريبا ,<br><br>أنا عندي ملف وورد في التعاريف هذي ورسمتين , على كلام الشباب الي قبلنا بتجي منها<br><br>وبالنسبه لباقي الأسئله بحاول ادور لكم<br><br>وانتو بدوركم الي يعرف شي يحطه هنا<br><br>وجزاكم الله خير<br><br>دعواتكم ,<br><br>​<span data-fid=\"stk-f616015-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f616015-0": {"name": "MKT-301_…_FINAL_EXAM.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mkt301/88737/6", "user": "user5961", "ts": 1274943657000, "tid": 88737, "pn": 6}}', 1274943657000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
